import type { SdkConfig, SdkConfigResponse } from './contracts';
import { request } from './http';
import { SDK_VERSION } from './version';

export interface ScriptSettings {
  projectId: string | null;
  endpoint: string | null;
}

/** Snippet attributes generated by First Five, with the 0.1.x names kept as aliases. */
const PROJECT_ATTRS = ['data-firstfive-project', 'data-project-id'];
const ENDPOINT_ATTRS = ['data-firstfive-api', 'data-endpoint'];

function firstAttr(el: Element, names: string[]): string | null {
  for (const n of names) {
    const v = el.getAttribute(n);
    if (v) return v;
  }
  return null;
}

/** Read settings from the loading script. Must be given the script captured at load time. */
export function readScriptSettings(script: HTMLScriptElement | null): ScriptSettings {
  if (!script) return { projectId: null, endpoint: null };
  const projectId = firstAttr(script, PROJECT_ATTRS);
  let endpoint = firstAttr(script, ENDPOINT_ATTRS);
  if (!endpoint && script.src) {
    try {
      endpoint = new URL(script.src, window.location.href).origin;
    } catch {
      endpoint = null;
    }
  }
  return { projectId, endpoint };
}

export function isFirstFiveScript(script: Element | null): boolean {
  return !!script && !!firstAttr(script, PROJECT_ATTRS);
}

export const SCRIPT_SELECTOR = PROJECT_ATTRS.map((a) => `script[${a}]`).join(',');

export function normalizeConfig(body: SdkConfigResponse, endpoint: string): SdkConfig {
  const apiBaseUrl = (body.api_base_url || endpoint).replace(/\/+$/, '');
  let firstFiveOrigin = body.first_five_origin ?? '';
  if (!firstFiveOrigin) {
    try {
      firstFiveOrigin = new URL(apiBaseUrl).origin;
    } catch {
      firstFiveOrigin = '';
    }
  }
  return {
    status: body.status,
    apiBaseUrl,
    allowed_origins: Array.isArray(body.allowed_origins) ? body.allowed_origins : [],
    event_allowlist: Array.isArray(body.event_allowlist) ? body.event_allowlist : [],
    custom_event_allowlist: Array.isArray(body.allowed_custom_events)
      ? body.allowed_custom_events
      : [],
    max_batch_events: Math.min(50, body.limits?.maxEventsPerBatch || 20),
    first_five_origin: firstFiveOrigin,
  };
}

export async function fetchConfig(endpoint: string, projectId: string): Promise<SdkConfig | null> {
  try {
    const res = await request<SdkConfigResponse>(
      `${endpoint}/api/sdk/config?project_id=${encodeURIComponent(projectId)}&sdk_version=${encodeURIComponent(SDK_VERSION)}`,
    );
    return res.status === 200 && res.body ? normalizeConfig(res.body, endpoint) : null;
  } catch {
    return null;
  }
}

export function originAllowed(config: SdkConfig, origin: string): boolean {
  return config.allowed_origins.includes(origin);
}
